import React, { useState } from 'react';
import CheckBoxes2 from '../../CheckBoxes/CheckBoxes2';
import { useEffect } from 'react';
import { useForm } from "react-hook-form"
import Tarjeta from '../../ComponentesFormulario/Tarjeta/Tarjeta';
import Boton from '../../Boton/Boton';
import Input from "../../Input/Input";
import './NuevoRol.css'

export default function NuevoRol({ onGuardar, token }) {


    const [todosPermisos, setTodosPermisos] = useState([]);

    const { register, handleSubmit, formState: { errors }, reset, setValue, watch, control } = useForm({
        defaultValues: {
            permisosRol: []
        }
    });

    // Obtener todos los permisos disponibles
    useEffect(() => {
        const obtenerPermisos = async () => {
            try {
                const respuesta = await fetch(`${import.meta.env.VITE_API_BASE_URL}/api/permiso`);
                const permisos = await respuesta.json();
                setTodosPermisos(permisos);
            } catch (error) {
                console.error("Error al obtener permisos:", error);
            }
        };

        obtenerPermisos();
    }, []);

    // POST PRIMERO GUARDO EL ROL Y SUS PERMISOS, EVELVO ESO EN UNA TRANSACCION EN EL BACKEND

    const onSubmit = async (data) => {
        try {
            
            //  Validación arreglo de permisos no vacio
                if (!data.permisosRol || data.permisosRol.length === 0) {
                alert("Debe seleccionar al menos un permiso para el rol.");
                return;
            }


            const rolResponse = await fetch(`${import.meta.env.VITE_API_BASE_URL}/api/rol`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'accept': 'application/json',
                    'Authorization': `Bearer ${token}`
                },
                body: JSON.stringify({
                    nombre_rol: data.nombre_rol,
                    permisos: data.permisosRol // aquí pasamos directamente el array de IDs
                })
            });

            if (!rolResponse.ok) {
                throw new Error('Error al crear el rol');
            }

            const nuevoRol = await rolResponse.json();
            console.log("Rol creado con permisos:", nuevoRol);

            reset();
            onGuardar();

        } catch (error) {
            console.error('Error completo:', error);
            alert('Error al crear el rol: ' + error.message);
        }
    };



    // Dividir permisos en columnas (opcional, para mejor visualización)
    const columnas = [];
    for (let i = 0; i < todosPermisos.length; i += 5) {
        columnas.push(todosPermisos.slice(i, i + 5));
    }


    ///LAYOUT

    return (
        <>
            <form onSubmit={handleSubmit(onSubmit)} className="__formulario_nuevo_rol">
                <div className="__cuerpo_nuevo_rol">
                    <Tarjeta descripcion="Nombre del Rol" forid="nombre_rol" mensajeError={errors.nombre_rol?.message}>
                        <Input
                            tipo="text"
                            id="nombre_rol"
                            {...register("nombre_rol", {
                                required: { value: true, message: "Ingrese nombre para el Rol" },
                                validate: (value) => value.trim() !== "" || "El nombre no puede estar vacío"
                            })}
                        />
                    </Tarjeta>

                    <Tarjeta descripcion="Permisos">
                        {columnas.length > 0 ? (
                            <div className="__checkboxes_columnas">
                                {columnas.map((columna, i) => (
                                    <div key={i} className="__columna_checkbox">
                                        <CheckBoxes2
                                            opciones={columna}
                                            name="permisosRol"
                                            setValue={setValue}
                                            watch={watch}
                                            soloLectura={false}
                                        />
                                    </div>
                                ))}
                            </div>
                        ) : (
                            <p>Cargando permisos...</p>
                        )}
                    </Tarjeta>
                </div>

                <div className='__boton_nuevo_rol'>
                    <Boton descripcion="Crear" submit habilitado></Boton>
                </div>
            </form>
        </>
    );
}
