import React from 'react';
import './CheckBoxes.css'

export default function CheckBoxes({ 
    opciones = [], 
    valoresSeleccionados = [], 
    soloLectura = false 
}) {
  
  const estaSeleccionado = (opcion) => {
    if (typeof opcion === 'object' && opcion.id) {
      return valoresSeleccionados.includes(opcion.id);
    }
    return valoresSeleccionados.includes(opcion);
  };

  const obtenerTexto = (opcion) => {
    if (typeof opcion === 'object' && opcion.nombre) {
      // Convertir primera letra a mayúscula y el resto a minúscula
      return opcion.nombre.charAt(0).toUpperCase() + opcion.nombre.slice(1).toLowerCase();
    }
    return opcion;
  };

  const obtenerValor = (opcion) => {
    if (typeof opcion === 'object' && opcion.id) {
      return opcion.id;
    }
    return opcion;
  };

  return (
    <div className="__checkboxes">
      {opciones.map((opcion, indice) => {
        const seleccionado = estaSeleccionado(opcion);
        const valor = obtenerValor(opcion);
        const texto = obtenerTexto(opcion);
        
        return (
          <label 
            key={indice}
            className={`${seleccionado ? '__labelSeleccionado' : '__labelCheckbox'}`}
          >
            <input
              className="__inputCheckbox"
              type="checkbox"
              value={valor}
              checked={seleccionado}
              onChange={() => {}}
              disabled={soloLectura}
              readOnly={soloLectura}
            />
            <span>{texto}</span>
          </label>
        );
      })}
    </div>
  );
}