import React, { useEffect } from 'react';
import './CheckBoxes.css'

export default function CheckBoxes2({ 
    opciones = [], 
    name, 
    valoresSeleccionados = [], 
    onFuncion, 
    setValue, 
    watch, 
    soloLectura = false 
}) {
  
  // Observamos el valor actual del campo en el formulario
  const seleccionados = watch ? (watch(name) || []) : valoresSeleccionados;

  // Sincronizar valores iniciales
  useEffect(() => {
    if (setValue && valoresSeleccionados.length > 0) {
      setValue(name, valoresSeleccionados, { shouldValidate: true });
    }
  }, []);

  const manejaCambio = (e) => {
    const { value, checked } = e.target;

    if (soloLectura) return;

    const valorNumerico = Number(value); // Convertir a número para coincidir con los IDs

    const nuevosSeleccionados = checked
      ? [...seleccionados, valorNumerico]
      : seleccionados.filter((id) => id !== valorNumerico);

    // Actualizar el formulario
    if (setValue) {
      setValue(name, nuevosSeleccionados, { shouldValidate: true });
    }
    
    if (onFuncion) onFuncion(nuevosSeleccionados);
  };

  const obtenerTexto = (opcion) => {
    if (typeof opcion === 'object' && opcion.nombre_permiso) {
      return opcion.nombre_permiso.charAt(0).toUpperCase() + opcion.nombre_permiso.slice(1).toLowerCase();
    }
    return String(opcion);
  };

  const obtenerValor = (opcion) => {
    if (typeof opcion === 'object' && opcion.id_permiso) {
      return opcion.id_permiso;
    }
    return opcion;
  };

  return (
    <div className="__checkboxes">
      {opciones.map((opcion, indice) => {
        const valor = obtenerValor(opcion);
        const texto = obtenerTexto(opcion);
        const estaSeleccionado = seleccionados.includes(valor);
        
        return (
          <label 
            key={indice}
            className={`${estaSeleccionado ? '__labelSeleccionado' : '__labelCheckbox'}`}
          >
            <input
              className="__inputCheckbox"
              type="checkbox"
              name={name}
              value={valor}
              checked={estaSeleccionado}
              onChange={manejaCambio}
              disabled={soloLectura}
            />
            <span>{texto}</span>
          </label>
        );
      })}
    </div>
  );
}